---
     1	import { expect, test } from "@playwright/test";
     2	import type { APIRequestContext } from "@playwright/test";
     3	
     4	/**
     5	 * End-to-end integration proof for the AI conversation practice pipeline —
     6	 * task 1.4. Runs only under the `conversation-practice` Playwright project
     7	 * (`npm run test:e2e -- --project=conversation-practice`), which owns its
     8	 * own real backend process via the conversation-backend-setup/-teardown
     9	 * dependency (see playwright.config.ts) rather than the shared `webServer`
    10	 * array, so the app's existing home/lesson-intro specs never boot a GPU
    11	 * backend.
    12	 *
    13	 * Chromium loops the fake-capture file continuously from stream start
    14	 * (`--use-file-for-fake-audio-capture`), so both fixture WAVs are padded
    15	 * with ~1s of leading/trailing silence — recording for 3s comfortably
    16	 * captures real speech regardless of exact click timing.
    17	 */
    18	
    19	const HEALTH_URL = "http://localhost:8000/health";
    20	const READY_TIMEOUT_MS = 4 * 60_000;
    21	const READY_POLL_INTERVAL_MS = 2_000;
    22	
    23	async function waitForBackendReady(request: APIRequestContext): Promise<void> {
    24		const deadline = Date.now() + READY_TIMEOUT_MS;
    25		let lastLoaded: Record<string, boolean> | null = null;
    26		while (Date.now() < deadline) {
    27			try {
    28				const res = await request.get(HEALTH_URL);
    29				if (res.ok()) {
    30					const body = (await res.json()) as {
    31						models_loaded: Record<string, boolean>;
    32					};
    33					lastLoaded = body.models_loaded;
    34					if (Object.values(lastLoaded).every(Boolean)) return;
    35				}
    36			} catch {
    37				// Backend not accepting connections yet — keep polling.
    38			}
    39			await new Promise((resolve) => setTimeout(resolve, READY_POLL_INTERVAL_MS));
    40		}
    41		const stalled = lastLoaded
    42			? Object.entries(lastLoaded)
    43					.filter(([, ready]) => !ready)
    44					.map(([name]) => name)
    45			: ["whisper", "judge", "tts"];
    46		throw new Error(
    47			`Backend did not become ready within ${READY_TIMEOUT_MS}ms — ` +
    48				`stalled model(s): ${stalled.join(", ") || "unknown (no /health response yet)"}`,
    49		);
    50	}
    51	
    52	test.describe("conversation practice — real backend, acceptable reply", () => {
    53		test.beforeAll(async ({ request }) => {
    54			await waitForBackendReady(request);
    55		});
    56	
    57		test("a fake-mic pass reply drives a real pass verdict (AC2)", async ({
    58			page,
    59		}) => {
    60			await page.goto("/thai-script/#/conversation");
    61			await expect(page.getByText("สบายดีไหม")).toBeVisible({ timeout: 30_000 });
    62	
    63			await page.getByRole("button", { name: "Record your reply" }).click();
    64			await page.waitForTimeout(3_000);
    65			await page.getByRole("button", { name: "Stop recording" }).click();
    66	
    67			// Transcript non-empty BEFORE the verdict — a capture-timing miss must
    68			// report as "nothing was heard", never as a false "the judge said fail".
    69			await expect(page.getByText("We heard:")).toBeVisible({ timeout: 30_000 });
    70			const transcript = await page.locator('span[lang="th"]').textContent();
    71			expect(transcript?.trim().length ?? 0).toBeGreaterThan(0);
    72	
    73			await expect(page.getByText("Good answer")).toBeVisible({
    74				timeout: 60_000,
    75			});
    76		});
    77	});
    78	
    79	// The off-topic-reply case (AC3) needs a different
    80	// `--use-file-for-fake-audio-capture` value, which Playwright only allows
    81	// via a file-top-level `test.use()` (a describe-scoped override "forces a
    82	// new worker" and is refused) — see conversation-practice-fail.spec.ts.
    83	
    84	test.describe("conversation practice — backend unreachable", () => {
    85		test("a simulated connection failure renders the not-running state without hanging (AC4)", async ({
    86			page,
    87		}) => {
    88			// No process is stopped and task 1.3's frozen base-URL constant is
    89			// never repointed — this produces exactly the `fetch` rejection the
    90			// adapter's `unavailable` path is already built to handle.
    91			await page.route("**/localhost:8000/**", (route) =>
    92				route.abort("connectionrefused"),
    93			);
    94			await page.goto("/thai-script/#/conversation");
    95			await expect(page.getByRole("alert")).toContainText("not running", {
    96				timeout: 15_000,
    97			});
    98		});
    99	});
   100	
   101	// AC5: a person actually listens to the opening question's synthesized audio
   102	// and confirms it's audible, intelligible Thai in the cloned voice. No
   103	// automated test can judge audio quality — see this task's manual
   104	// verification note.

